-- Seeds real purchase-order history from po_lines_clean.csv (16 POs, 317 lines)
-- supplied for lead-time measurement, and the initial lead_time_products /
-- lead_time_name_mappings rows for every distinct style found in it.
--
-- fabric_meters_on_po arrived as free text ("99 Meter", "29,5 Meter" with an
-- Indonesian decimal comma, or "-") - normalized to a plain number here
-- (strip "Meter"/"meter", comma -> dot, "-" -> null). Every other numeric
-- column in the source was already a plain number.
--
-- Every distinct `style` string gets its own lead_time_products row and a
-- 1:1 auto_created mapping - never merged automatically, per migration 0027's
-- comment on lead_time_name_mappings. One pair is flagged for a human to
-- confirm rather than silently combined: 'Shadow - Long Sleeve' (PO 135,
-- Black only) and 'Shadow Shirt' (POs 146/148/150, also Black only) look like
-- they could be the same garment under two different names across time -
-- or not. Left as two separate products until confirmed.

insert into purchase_orders (po_no, po_date) values
  ('132', '2025-03-20'),
  ('133', '2025-03-21'),
  ('134', '2025-06-05'),
  ('135', '2025-06-18'),
  ('136', '2025-07-17'),
  ('137', '2025-08-11'),
  ('139', '2025-09-20'),
  ('143', '2025-11-19'),
  ('146', '2026-01-12'),
  ('147', '2025-02-18'),
  ('148', '2026-04-15'),
  ('149', '2026-04-15'),
  ('150', '2026-06-24'),
  ('151', '2026-09-15'),
  ('152', '2026-06-24'),
  ('153', '2026-10-08')
on conflict (po_no) do nothing;

insert into lead_time_products (canonical_name, is_garment) values
  ('Affine Shirt', true),
  ('Benang Polo', false),
  ('Button Hook', false),
  ('Chino Pants', true),
  ('Kancing Hook', false),
  ('Linen Angel', true),
  ('Linen Pants', true),
  ('Lining Swimshort', false),
  ('POLO', true),
  ('Polo Shirt', true),
  ('SAMPLE Affine', false),
  ('Shadow - Long Sleeve', true),
  ('Shadow Shirt', true),
  ('Swim Short', true),
  ('Zipper', false)
on conflict (canonical_name) do nothing;

insert into lead_time_name_mappings (raw_name, lead_time_product_id, auto_created, note) values
  ('Affine Shirt', (select id from lead_time_products where canonical_name = 'Affine Shirt'), true, NULL),
  ('Benang Polo', (select id from lead_time_products where canonical_name = 'Benang Polo'), true, NULL),
  ('Button Hook', (select id from lead_time_products where canonical_name = 'Button Hook'), true, NULL),
  ('Chino Pants', (select id from lead_time_products where canonical_name = 'Chino Pants'), true, NULL),
  ('Kancing Hook', (select id from lead_time_products where canonical_name = 'Kancing Hook'), true, NULL),
  ('Linen Angel', (select id from lead_time_products where canonical_name = 'Linen Angel'), true, NULL),
  ('Linen Pants', (select id from lead_time_products where canonical_name = 'Linen Pants'), true, NULL),
  ('Lining Swimshort', (select id from lead_time_products where canonical_name = 'Lining Swimshort'), true, NULL),
  ('POLO', (select id from lead_time_products where canonical_name = 'POLO'), true, NULL),
  ('Polo Shirt', (select id from lead_time_products where canonical_name = 'Polo Shirt'), true, NULL),
  ('SAMPLE Affine', (select id from lead_time_products where canonical_name = 'SAMPLE Affine'), true, NULL),
  ('Shadow - Long Sleeve', (select id from lead_time_products where canonical_name = 'Shadow - Long Sleeve'), true, 'Possibly the same garment as ''Shadow Shirt'' under an earlier name (PO 135 predates 146/148/150, both Black-only) - confirm and merge by repointing this mapping if so.'),
  ('Shadow Shirt', (select id from lead_time_products where canonical_name = 'Shadow Shirt'), true, 'Possibly the same garment as ''Shadow - Long Sleeve'' under a later name (see that mapping''s note) - confirm before merging.'),
  ('Swim Short', (select id from lead_time_products where canonical_name = 'Swim Short'), true, NULL),
  ('Zipper', (select id from lead_time_products where canonical_name = 'Zipper'), true, NULL)
on conflict (raw_name) do nothing;

