  status, is_garment, has_receipt_columns, b1_date, b2_date, b3_date,
  lead_time_product_id, flags
)
select
  po.id, v.style, v.colorway, v.size, v.sku_key, v.material, v.fabric_meters_on_po,
  v.qty_ordered, v.unit_price_idr, v.b1_qty, v.b2_qty, v.b3_qty, v.qty_received_total,
